      "achados": [
        {
          "proposicao": "O estudo realizou ensaios de corrosão em materiais de tubulação expostos a diferentes meios contendo água salgada e hipoclorito de sódio, incluindo solução pura de NaClO, para investigar a influência desses ambientes no processo corrosivo.",
          "trechos": [
            "E1b3a6c023807cdc0:0:691",
            "E1b3a6c023807cdc0:691:1391",
            "E1b3a6c023807cdc0:1391:2082"
          ],
          "condicoes": [
            "avaliação experimental de corrosão",
            "materiais de tubulação e anéis de uma linha overboard",
            "meios com água do mar sintética, água de processo e hipoclorito"
          ],
          "limites": [
            "o trecho descreve desenho experimental e meios de ensaio, não resultados finais de taxa de corrosão",
            "os valores numéricos de concentração estão mascarados"
          ]
        },
        {
          "proposicao": "Os meios de ensaio incluíram tanto água do mar sintética com diferentes ajustes de hipoclorito quanto amostra de água do Wellstream Cooler com e sem ajuste de hipoclorito, indicando comparação entre água sintética e água real de operação.",
          "trechos": [
            "E1b3a6c023807cdc0:1391:2082"
          ],
          "condicoes": [
            "comparação entre matrizes aquosas distintas",
            "ajuste de hipoclorito em parte das amostras"
          ],
          "limites": [
            "as concentrações em ppm foram apagadas e não podem ser reconstruídas",
            "o trecho não informa desempenho relativo entre os meios"
          ]
        }
      ]
    },
    {
      "id": "E3a26314cd08d6367",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O trabalho mapeou o circuito de injeção de hipoclorito de sódio desde o armazenamento até a linha overboard para avaliar a influência do NaClO no processo corrosivo de equipamentos e tubulações e apoiar eficiência operacional e redução de custos.",
          "trechos": [
            "E3a26314cd08d6367:0:697"
          ],
          "condicoes": [
            "contexto de ativo offshore",
            "análise do circuito de injeção de NaClO"
          ],
          "limites": [
            "o trecho apresenta motivação e escopo do estudo, não um resultado conclusivo",
            "não fornece critério operacional de dosagem ou controle"
          ]
        },
        {
          "proposicao": "A falha corrosiva investigada foi localizada no descarte de água salgada ao mar, na região da linha overboard conectada ao sistema de refrigeração e ao sistema de descarte de cascalho.",
          "trechos": [
            "E3a26314cd08d6367:697:1394"
          ],
          "condicoes": [
            "sistema específico mapeado no estudo",
            "região de descarte de água salgada"
          ],
          "limites": [
            "relato de instalação específica",
            "não demonstra, por si só, causalidade exclusiva do hipoclorito na falha"
          ]
        },
        {
          "proposicao": "A linha objeto de pesquisa era de aço carbono ASTM A106 Gr B, o que vincula a discussão de integridade e corrosão a esse material específico no caso estudado.",
