          ]
        },
        {
          "proposicao": "O cloro ou hipoclorito dissolvido é tratado como agente oxidante e despolarizador análogo ao oxigênio na ação corrosiva, e a fonte apresenta equivalência entre cloro dissolvido e oxigênio dissolvido para essa análise.",
          "trechos": [
            "E8bdf98766682732a:695:1393"
          ],
          "condicoes": [
            "análise da interação entre cloro/hipoclorito e oxigênio dissolvido"
          ],
